from solution import bind_local


class ReviewProbe(unittest.TestCase):
    def test_finite_nested_symbol_value(self):
        value = []
        cursor = value
        for _ in range(600):
            child = []
            cursor.append(child)
            cursor = child
        error = None
        try:
            bind_local('module', {'value': value})
        except Exception as exc:
            error = type(exc).__name__
        self.assertIsNone(error)


if __name__ == '__main__':
    unittest.main()

