import unittest
from collections import OrderedDict

from solution import bind_local


class BindLocalTests(unittest.TestCase):
    def test_renames_matching_key_not_matching_value(self):
        symbols = OrderedDict([
            ("first", "module"),
            ("module", {"nested": [1, 2]}),
            ("last", 3),
        ])
        result = bind_local("module", symbols)
        self.assertEqual(list(result), ["first", "module_value", "last"])
        self.assertEqual(result, {
            "first": "module",
            "module_value": {"nested": [1, 2]},
            "last": 3,
        })
        self.assertNotIn("module", result)

    def test_empty_mapping(self):
        self.assertEqual(bind_local("valid_name", {}), {})

    def test_values_are_deep_copied_and_input_is_unchanged(self):
        nested = {"items": [[1], [2]]}
        symbols = {"value": nested}
        result = bind_local("module", symbols)
        self.assertIsNot(result, symbols)
        self.assertIsNot(result["value"], nested)
        self.assertIsNot(result["value"]["items"], nested["items"])
        result["value"]["items"][0].append(99)
        self.assertEqual(symbols, {"value": {"items": [[1], [2]]}})

    def test_generated_name_collision(self):
        symbols = OrderedDict([
            ("module", 1),
            ("module_value", 2),
        ])
        with self.assertRaises(ValueError):
            bind_local("module", symbols)

    def test_module_name_validation(self):
        for value in (None, 1, True):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    bind_local(value, {})
        for value in ("", "not valid", "2module"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    bind_local(value, {})

    def test_symbols_and_key_validation(self):
        for value in ([], None, "mapping"):
            with self.assertRaises(TypeError):
                bind_local("module", value)
        with self.assertRaises(TypeError):
            bind_local("module", {1: "value"})
        for key in ("", "has space", "3name"):
            with self.subTest(key=key):
                with self.assertRaises(ValueError):
                    bind_local("module", {key: "value"})


if __name__ == "__main__":
    unittest.main()

